CREATE DATABASE IF NOT EXISTS lynx CHARACTER SET utf8mb4; USE lynx;
CREATE TABLE User(Id INT AUTO_INCREMENT PRIMARY KEY,FirstName VARCHAR(60) NOT NULL,LastName VARCHAR(60) NOT NULL,Email VARCHAR(150) NOT NULL UNIQUE,PasswordHash VARCHAR(255) NOT NULL,Role ENUM('Customer','Admin') NOT NULL DEFAULT 'Customer');
CREATE TABLE Category(Id INT AUTO_INCREMENT PRIMARY KEY,Name VARCHAR(60) NOT NULL,Description TEXT);
CREATE TABLE Destination(Id INT AUTO_INCREMENT PRIMARY KEY,Name VARCHAR(100) NOT NULL,Country VARCHAR(80) NOT NULL,Region VARCHAR(80),Description TEXT,Image VARCHAR(255),BestTimeToVisit VARCHAR(120),TravelTips TEXT);
CREATE TABLE Expedition(Id INT AUTO_INCREMENT PRIMARY KEY,Name VARCHAR(150) NOT NULL,ShortDescription VARCHAR(255),Description TEXT,Itinerary TEXT,Included TEXT,NotIncluded TEXT,Price DECIMAL(8,2) NOT NULL,DurationDays TINYINT NOT NULL CHECK(DurationDays BETWEEN 1 AND 5),Difficulty ENUM('Easy','Moderate','Challenging') NOT NULL,MaxGroupSize SMALLINT NOT NULL,DepartureLocation VARCHAR(120),FeaturedImage VARCHAR(255),StartDate DATE NOT NULL,EndDate DATE NOT NULL,CategoryId INT NOT NULL,DestinationId INT NOT NULL,IsFeatured BOOL DEFAULT 0,IsActive BOOL DEFAULT 1,
 FOREIGN KEY(CategoryId) REFERENCES Category(Id),FOREIGN KEY(DestinationId) REFERENCES Destination(Id));
CREATE TABLE ExpeditionPhoto(Id INT AUTO_INCREMENT PRIMARY KEY,ExpeditionId INT NOT NULL,Image VARCHAR(255) NOT NULL,FOREIGN KEY(ExpeditionId) REFERENCES Expedition(Id) ON DELETE CASCADE);
CREATE TABLE Booking(Id INT AUTO_INCREMENT PRIMARY KEY,UserId INT NOT NULL,ExpeditionId INT NOT NULL,NumberOfTravelers SMALLINT NOT NULL,BookingDate DATETIME DEFAULT CURRENT_TIMESTAMP,Status ENUM('Pending','Confirmed','Rejected','Cancelled') DEFAULT 'Pending',CustomerMessage TEXT,AdminMessage TEXT,FOREIGN KEY(UserId) REFERENCES User(Id),FOREIGN KEY(ExpeditionId) REFERENCES Expedition(Id));
CREATE TABLE Favorite(Id INT AUTO_INCREMENT PRIMARY KEY,UserId INT NOT NULL,ExpeditionId INT NOT NULL,CreatedAt DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE(UserId,ExpeditionId),FOREIGN KEY(UserId) REFERENCES User(Id) ON DELETE CASCADE,FOREIGN KEY(ExpeditionId) REFERENCES Expedition(Id) ON DELETE CASCADE);
CREATE TABLE Review(Id INT AUTO_INCREMENT PRIMARY KEY,UserId INT NOT NULL,ExpeditionId INT NOT NULL,Rating TINYINT NOT NULL CHECK(Rating BETWEEN 1 AND 5),Comment TEXT,CreatedAt DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE(UserId,ExpeditionId),FOREIGN KEY(UserId) REFERENCES User(Id),FOREIGN KEY(ExpeditionId) REFERENCES Expedition(Id) ON DELETE CASCADE);
CREATE TABLE JournalPost(Id INT AUTO_INCREMENT PRIMARY KEY,Title VARCHAR(200) NOT NULL,Slug VARCHAR(220) NOT NULL UNIQUE,Content TEXT NOT NULL,AuthorId INT NOT NULL,PublishedAt DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(AuthorId) REFERENCES User(Id));
CREATE TABLE ContactMessage(Id INT AUTO_INCREMENT PRIMARY KEY,Name VARCHAR(100),Email VARCHAR(150),Subject VARCHAR(200),Message TEXT,SubmittedAt DATETIME DEFAULT CURRENT_TIMESTAMP,IsRead BOOL DEFAULT 0);
CREATE TABLE Notification(Id INT AUTO_INCREMENT PRIMARY KEY,UserId INT NOT NULL,Message VARCHAR(255) NOT NULL,CreatedAt DATETIME DEFAULT CURRENT_TIMESTAMP,IsRead BOOL DEFAULT 0,FOREIGN KEY(UserId) REFERENCES User(Id) ON DELETE CASCADE);
